package java.util.concurrent.atomic;
public class AtomicInteger extends Number implements java.io.Serializable {
 private volatile int value; public AtomicInteger(){} public AtomicInteger(int initialValue){value=initialValue;} public final int get(){return value;} public final void set(int v){value=v;} public final void lazySet(int v){set(v);} public final synchronized int getAndSet(int v){int old=value;value=v;return old;} public final synchronized boolean compareAndSet(int expect,int update){if(value!=expect)return false;value=update;return true;} public final boolean weakCompareAndSet(int expect,int update){return compareAndSet(expect,update);} public final synchronized int getAndIncrement(){return value++;} public final synchronized int getAndDecrement(){return value--;} public final synchronized int getAndAdd(int d){int old=value;value+=d;return old;} public final synchronized int incrementAndGet(){return ++value;} public final synchronized int decrementAndGet(){return --value;} public final synchronized int addAndGet(int d){return value+=d;} public int intValue(){return (int)value;} public long longValue(){return (long)value;} public float floatValue(){return (float)value;} public double doubleValue(){return (double)value;} public String toString(){return String.valueOf(value);} }
